(45811, 'Job 38:41', 'Job', 38, 41, 'کارغانو دپاره د خوراک بندوبست څوک کوى، کله چې د هغوئ بچى خُدائ پاک ته ژړا کوى، او د خوراک د نشتوالى په وجه سرګردانه ګرځى؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job38_verse_41.mp3', '', 1761754199, 1761754199),
(45812, 'Nehemiah 9:3', 'Nehemiah', 9, 3, 'هغوی درې ساعته ولاړ وو او د خپل څښتن خدای تورات ته یې غوږ نیولی ؤ او درې ساعته نور یې په خپلو ګناهونو باندې اقرار وکړ او د خپل څښتن خدای عبادت یې وکړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah9_verse_3.mp3', '', 1761754199, 1761754199),
(45813, 'Nehemiah 9:4', 'Nehemiah', 9, 4, 'یشوع، باني، قدمي ییل، شبنیا، بوني، شربیا، باني او کناني په هغه منبر باندې ودرېدل چې د لاویانو دپاره ؤ او په لوړ اواز یې خپل څښتن خدای ته زارۍ وکړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah9_verse_4.mp3', '', 1761754199, 1761754199),
(45814, 'Nehemiah 9:5', 'Nehemiah', 9, 5, 'دغو نورو لاویانو خلکو ته د عبادت دپاره بلنه ورکړه: یشوع، قدمي ییل، باني، حشبنیا، شربیا، هودیا، شبنیا او فتحیا. هغوی وویل: پاڅېږئ وکړئ ستاینه د خپل څښتن خدای ستاینه وکړئ د هغه د تل دپاره هر یو دې وکړي د هغه د جلالي نوم صفت ثنا دې وي ستا پر جلاله نوم ته چې لوی دی ټولو صفتونو څخه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah9_verse_5.mp3', '', 1761754199, 1761754199),
(45815, 'Nehemiah 9:6', 'Nehemiah', 9, 6, 'ته څښتن یې یوازې ته څښتن یې تا دي جوړ کړي اسمانونه ټول د ستورو سره تا پیدا کړې ځمکه، بحیره او هر څه چې دي هغو کې تا وربخښلی دی ژوندون ټولو ته تاته سجده کړي ستا عبادت کړي اسماني ځواکونه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah9_verse_6.mp3', '', 1761754199, 1761754199),
(45816, 'Nehemiah 9:7', 'Nehemiah', 9, 7, 'ته یې هغه څښتن خدای چا چې کړ غوره ابرام تا راوویست هغه د کلدانیانو د اور د ښار څخه او د هغه نوم دې ابراهیم کېښود', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah9_verse_7.mp3', '', 1761754199, 1761754199),
(45817, 'Nehemiah 9:8', 'Nehemiah', 9, 8, 'ته شوې پوه چې هغه تاته وفادار دی او تا وکړ د هغه سره لوظ تا وعده وکړه چې اولادې ته د هغه به ورکړې د کنعانیانو ځمکه هم د حیتیانو، اموریانو ځمکه د فرزیانو، یبوسیانو، جرجاشیانو ځمکه ته ودرېدلې خپله وعده باندې ځکه چې ته یې وفادار', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah9_verse_8.mp3', '', 1761754199, 1761754199),
(45818, 'Nehemiah 9:9', 'Nehemiah', 9, 9, 'تا ولید مصر کې زمونږه د نیکونو کړاو کله چې وو هغوی سرې بحیرې سره تا واورېدلې چې وهلې هغوی چیغې د کومک په خاطر', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah9_verse_9.mp3', '', 1761754199, 1761754199),
(45819, 'Nehemiah 9:10', 'Nehemiah', 9, 10, 'تا وښودلې معجزې حیرانوونکې د فرعون او د هغه د درباریانو خلاف او د هغه وطن د خلکو خلاف ځکه ته پوهېدلې چې وکړ څنګه کبرجن چلند دوی زمونږ نیکونو سره تا وګټلو داسې نوم چې دی پاتې تر ننه پورې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah9_verse_10.mp3', '', 1761754199, 1761754199),
(45820, 'Nehemiah 9:11', 'Nehemiah', 9, 11, 'لاره دې جوړه کړه خپل قوم ته د بحیرې په منځ کې پورې وتل هغوی د بحیرې له لارې په وچه ځمکه باندې هغوی دې کړل ژورو اوبو ته ګوزار چې ورپسې وو ستا ولس پسې ډوب شول داسې لکه تیږه چې شي ډوبه توفاني بحر کې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah9_verse_11.mp3', '', 1761754199, 1761754199),
(45821, 'Nehemiah 9:12', 'Nehemiah', 9, 12, 'د ورځې کړه دې لارښوونه ورته د ستنې په شان ورېځ باندې روښانوله ورته لاره دې د شپې له خوا نه په هغه اور باندې چې ؤ د ستنې په شان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah9_verse_12.mp3', '', 1761754199, 1761754199),
(45822, 'Nehemiah 9:13', 'Nehemiah', 9, 13, 'ته شوې راښکته د سینا غره باندې دوی ته دې وکړلې خبرې له اسمانه څخه ورکړله زده کړه دې هغوی ته د باور نه ډکه ښه قوانین عادلانه دې ورکړل', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah9_verse_13.mp3', '', 1761754199, 1761754199),
(45823, 'Nehemiah 9:14', 'Nehemiah', 9, 14, 'دوی ته دې وښودله خپله سپېڅلې ورځ د سبت ورته دې ورکړل قوانین او تورات په وسیله د خدمتګار خپل موسی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah9_verse_14.mp3', '', 1761754199, 1761754199),
(45824, 'Nehemiah 9:15', 'Nehemiah', 9, 15, 'کله چې وږي شول هغوی تا ورته ورکړله ډوډۍ له اسمانه څخه ورته دې ورکړلې د ګټ نه اوبه چې کله تږي شول ودې ویل هغوی ته چې ورننوځي ونیسي هغه ځمکه چې تا قسم کړی ؤ چې ورته وربه یې کړې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah9_verse_15.mp3', '', 1761754199, 1761754199),
(45825, 'Nehemiah 9:16', 'Nehemiah', 9, 16, 'خو زمونږ نیکونه شول سرزوري مغرور سرغړونه یې وکړه ستا د امرونو څخه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah9_verse_16.mp3', '', 1761754199, 1761754199),
(45826, 'Nehemiah 9:17', 'Nehemiah', 9, 17, 'سرغړونه یې وکړه ستا له اطاعته څخه هغوی کړې هېرې معجزې چې ښودلې وې تا هغوی د خپلې سرزورۍ په سبب کړلو یو مشر غوره چې د مصر غلامۍ ته بېرته بوځي هغوی خو ته بخښونکی خدای یې ته مهربانه او رحیم یې ته نه په قهرېږې ته زر لویه ده مینه تلپاتې ستا تا پرېنښودل هغوی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah9_verse_17.mp3', '', 1761754199, 1761754199),
(45827, 'Nehemiah 9:18', 'Nehemiah', 9, 18, 'حتی جوړ کړ هغوی بت د خوسي په شکل او ویل یې چې دا هغه خدای دی چې یې راوویستئ له مصر څخه ای څښتنه! وکړ څومره سپکاوی ستا هغوی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah9_verse_18.mp3', '', 1761754199, 1761754199),
(45828, 'Nehemiah 9:19', 'Nehemiah', 9, 19, 'خو تا پرېنښودل هغوی هلته په دښته کې ځکه ډېر زیات دي رحمونه ستا لېرې دې نه کړه ورېځ او اور هغوی نه ورېځ به د ورځې ورته لار ښودله اور به د شپې رڼا کوله لاره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah9_verse_19.mp3', '', 1761754199, 1761754199),
(45829, 'Nehemiah 9:20', 'Nehemiah', 9, 20, 'د خپل نېک روح په وسیله دې لارښوونه د هغوی وکړه تا د خوراک دپاره من ورکاوه او اوبه د څښاک دپاره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah9_verse_20.mp3', '', 1761754199, 1761754199),
(45830, 'Nehemiah 9:21', 'Nehemiah', 9, 21, 'ودې ساتل هغوی په دښته کې څلوېښت کاله هېڅکله نه شول دوی محتاج هېڅ شي ته نه شوې زړې د هغوی جامې هېڅکله نه پړسېدې د هغوی پښې له درده', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah9_verse_21.mp3', '', 1761754199, 1761754199),
(45831, 'Nehemiah 9:22', 'Nehemiah', 9, 22, 'ورته دې ورکړل پاچاهیانې او قومونه په هر ځای کې دې اباد کړل هغوی ویې نیولو د سیحون پاچا حشبون هېواد هم یې د عوج پاچا باشان هېواد', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah9_verse_22.mp3', '', 1761754199, 1761754199),
(45832, 'Nehemiah 9:23', 'Nehemiah', 9, 23, 'تا ورکړل دومره زیات بچي هغوی ته دومره لکه چې ستوري وي اسمان کې تا راوستل هغه وطن ته هغوی چې د ورکولو دې وعده کړې وه د هغوی نیکونو سره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah9_verse_23.mp3', '', 1761754199, 1761754199),
(45833, 'Nehemiah 9:24', 'Nehemiah', 9, 24, 'نو ونیوله هغوی د کنعان خاوره تا اوسېدونکي کړل مغلوب هغوی ته د هغه ځای تا قوت ورکړ خپل قوم ته چې هرڅه غواړي هغوی ویې کړي د کنعان خلکو سره او هم یې پاچاهانو سره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah9_verse_24.mp3', '', 1761754199, 1761754199),
(45834, 'Nehemiah 9:25', 'Nehemiah', 9, 25, 'ستا قوم ونیول دېوال لرونکي ښارونه او هم یې ونیوله ځمکه حاصلخیزه د ډېرو ښو شیانو ډک کورونه او د لا پخوا نه کیندل شوې د اوبو ذخیرې ویې نیولې د زیتونو ونې او هم مېوه دارې ونې او هم د انګور باغونه وخوړل ټول هغه شیان چې یې غوښتل شول چاغ خوړلو سره چې دې ورکړي وو هغوی ته ټول ښه شيان هغوی ترې خوند واخیست', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah9_verse_25.mp3', '', 1761754199, 1761754199),
(45835, 'Nehemiah 9:26', 'Nehemiah', 9, 26, 'خو نافرمانه شو ستا قوم او شو یاغي د ستا نه هغوی کړه شا ستا شریعت ته کړل یې مړه ستا نبیان خبرداری یې چې ورکړی ؤ هغوی ته چې دروګرځي بیا ستا خواته هغوی کړی ستا توهین دی هر وخت', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah9_verse_26.mp3', '', 1761754199, 1761754199),
(45836, 'Nehemiah 9:27', 'Nehemiah', 9, 27, 'نو تا په لاس ورکړل هغوی خپلو دښمنانو ته چې هغوی وکړ بد چلند ورسره خو هغوی وکړ تاته سوال مرستې ته د خپل تکلیف په وخت کې تا دعاګانې د هغوی اسمان نه واورېدلې د خپل لوی رحم په سبب ودې لېږل ژغورونکي چې کړي خلاص هغوی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah9_verse_27.mp3', '', 1761754199, 1761754199),
(45837, 'Nehemiah 9:28', 'Nehemiah', 9, 28, 'کله چې سوله راغله بیا هغوی وکړه ګناه ستا په خلاف او تا بیا ورکړل هغوی د دښمنانو لاس ته چې حکومت وکړي په هغوی باندې خو بیاهم کله چې وویسته توبه هغوی ستا نه یې سوال وکړ چې وژغورې دوی تا په اسمان کې هغه واورېده او په خپل رحمت دې وژغورل څو څو ځله هغوی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah9_verse_28.mp3', '', 1761754199, 1761754199),
(45838, 'Nehemiah 9:29', 'Nehemiah', 9, 29, 'خبرداری دې ورکړ دوی ته چې بېرته راشي ستا شریعت ته خو هغوی ونه منل ستا قوانین په خپل غرور کې که څه هم په قوانینو ستا تلل د ژوندانه لاره ده خو شول سرزوري او سخت زړي هغوی او اطاعت یې نه کړ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah9_verse_29.mp3', '', 1761754199, 1761754199),
(45839, 'Nehemiah 9:30', 'Nehemiah', 9, 30, 'کلونه صبر وکړ تا او خبرداری دې ورکړ دوی ته په خپل روح باندې په وسیله د نبیانو خو وو کاڼه ستا خلک، تا پرې حاکم کړل نور قومونه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah9_verse_30.mp3', '', 1761754199, 1761754199),
(45840, 'Nehemiah 9:31', 'Nehemiah', 9, 31, 'خو بیاهم د خپل لوی رحمت په سبب تا پرېنښودل هغوی او نه دې نابود کړل هغوی ته مهربانه او رحیم خدای یې!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah9_verse_31.mp3', '', 1761754199, 1761754199),
(45841, 'Nehemiah 9:32', 'Nehemiah', 9, 32, 'ای زمونږ خدایه څومره لوی یې ته څومره ځواکمن او وېروونکی یې ته وفادارۍ سره ولاړ یې په خپل لوظ باندې دغه سختۍ او کړاوونه چې تېر کړي دي مونږ ستا په نظر کې باید نه شي بې ارزښته ښکاره له هغې ورځې نه تر ننه پورې چې کامیاب شوي دي په مونږ د آشور پاچاهان ‎ ډېرې بلاوې نازل شوې په مونږ ټولو په شاهانو او مشرانو زمونږ په کاهنانو، نبیانو او نیکونو زمونږ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah9_verse_32.mp3', '', 1761754199, 1761754199),
(45842, 'Nehemiah 9:33', 'Nehemiah', 9, 33, 'ته وې په حقه چې هر ځل دې راکړه مونږ ته سزا که څه هم مونږه کړې ګناه خو وفادار یې ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah9_verse_33.mp3', '', 1761754199, 1761754199),
(45843, 'Nehemiah 9:34', 'Nehemiah', 9, 34, 'پاچاهانو زمونږ، زمونږ مشرانو، کاهنانو او نیکونو زمونږ ستا په شریعت باندې عمل ونه کړ هغوی ونه نیوه غوږ خبرداریو او حکمونو ته ستا', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah9_verse_34.mp3', '', 1761754199, 1761754199),
(45844, 'Nehemiah 9:35', 'Nehemiah', 9, 35, 'لوی برکت دې ورکړ د پاچاهۍ هغوی ته هم پرېمانه شتمني او حاصلخېزه ځمکه خو هغوی نه وکړ عبادت ستا او نه یې پرېښودلې خپلې بدۍ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah9_verse_35.mp3', '', 1761754199, 1761754199),
(45845, 'Nehemiah 9:36', 'Nehemiah', 9, 36, 'ګوره مونږ یو نن غلامان چې دې ورکړې وه زمونږ نیکونو ته حاصلخېزه ځمکه چې یې مېوې او ښه فصلونه وخوري وګوره نن مونږ غلامان یو په کې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah9_verse_36.mp3', '', 1761754199, 1761754199),
(45846, 'Nehemiah 9:37', 'Nehemiah', 9, 37, 'اخلي پرېمانه حاصلات د ځمکې دا پاچاهان چې دې ټاکلي دي په مونږ باندې ځکه چې کړې ده ګناه مونږه چې یې وي خوښه هرڅه کړي یې په مونږ او په څارویو زمونږ لوی مصیبت کې ګرفتار یو مونږ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah9_verse_37.mp3', '', 1761754199, 1761754199),
(45847, 'Nehemiah 9:38', 'Nehemiah', 9, 38, 'د هغو ټولو پېښو له امله چې وشوې، مونږ د اسراییلو قوم یو لیکل شوی ټینګ لوظ کوو او زمونږ مشران، لاویان او زمونږ کاهنان به په هغه باندې خپل مهرونه ولګوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah9_verse_38.mp3', '', 1761754199, 1761754199),
(45848, 'Amos 5:1', 'Amos', 5, 1, 'ای د اسراییلو خلکو، دې د ویر سندرې ته چې ستاسو دپاره یې وایم غوږ ونیسئ:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos5_verse_1.mp3', '', 1761754199, 1761754199),
(45849, 'Amos 5:2', 'Amos', 5, 2, 'راوغورځېدله اسراییلۍ پېغله بیا به هېڅکله راپورته نه شي پرېښودل شوې ده هغه په خپل وطن کې هېڅوک نشته چې کړي راپورته هغه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos5_verse_2.mp3', '', 1761754199, 1761754199),
(45850, 'Amos 5:3', 'Amos', 5, 3, 'څښتن تعالی داسې وایي: «د یو ښار نه زر تنه عسکر لېږل کیږي، خو یوازې سل تنه یې بېرته راستنیږي او بل ښار سل تنه لېږي، خو یوازې لس تنه ورڅخه بېرته راستنیږي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos5_verse_3.mp3', '', 1761754199, 1761754199),
(45851, 'Amos 5:4', 'Amos', 5, 4, 'څښتن د اسراییلو خلکو ته داسې وایي: «ماته راشئ، نو تاسو به ژوندي پاتې شئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos5_verse_4.mp3', '', 1761754199, 1761754199),
(45852, 'Amos 5:5', 'Amos', 5, 5, 'ما په بیت‌ییل کې مه لټوئ، جلجال ته مه ځئ او بیرشبع ته سفر مه کوئ، ځکه چې د جلجال خلک به خامخا جلاوطنه شي او بیت‌ییل به له منځه لاړ شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos5_verse_5.mp3', '', 1761754199, 1761754199),
(45853, 'Amos 5:6', 'Amos', 5, 6, 'څښتن ته ورشئ، نو تاسو به ژوندي پاتې شئ. که ورنه شئ، نو هغه به لکه د اور په شان د اسراییلو په خلکو باندې رانازل شي. دا اور به د بیت‌ییل خلک وسوځوي او هېڅوک به نه شي کولای چې هغه اور مړ کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos5_verse_6.mp3', '', 1761754199, 1761754199),
(45854, 'Amos 5:7', 'Amos', 5, 7, 'افسوس په تاسو، خو تاسو انصاف په زهرو بدل کړی او عدالت مو تر پښو لاندې کړی دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos5_verse_7.mp3', '', 1761754199, 1761754199),
(45855, 'Amos 5:8', 'Amos', 5, 8, 'چې پیدا کړي دي چا د ثریا او د جبار ستوري هغه څوک چې بدلوي تیاره د سهار په رڼا او ورځ په شپه باندې هغه څوک چې راغواړي اوبه د بحر او اوروي یې په ځمکه د هغه نوم دی څښتن', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos5_verse_8.mp3', '', 1761754199, 1761754199),
(45856, 'Amos 5:9', 'Amos', 5, 9, 'هغه له منځه وړي قوي خلک او ورانوي یې کلاګانې قوي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos5_verse_9.mp3', '', 1761754199, 1761754199),
(45857, 'Amos 5:10', 'Amos', 5, 10, 'تاسو د هغه چا نه کرکه کوئ چې بې‌انصافۍ ته بد وایي او په محکمه کې رښتیا وایي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos5_verse_10.mp3', '', 1761754199, 1761754199),
(45858, 'Amos 5:11', 'Amos', 5, 11, 'تاسو غریبان تر پښو لاندې کوئ او غلې په مالیه کې ورڅخه په زوره اخلئ. نو تاسو چې د ښایسته تیږو څخه کوم کورونه جوړ کړي دي، په هغو کې به ونه اوسېږئ او نه به د هغو ښایسته تاکونو چې تاسو یې کرئ، شراب وڅښئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos5_verse_11.mp3', '', 1761754199, 1761754199),
(45859, 'Amos 5:12', 'Amos', 5, 12, 'ځکه زه پوهېږم چې ستاسو ګناهونه څومره زیات دي او څومره ډېر جرمونه مو کړي دي. تاسو نېکان خلک ځوروئ، رشوتونه اخلئ او په محکمو کې د دې مخنیوی کوئ چې غریبان دې خپل حقونه تر‌لاسه کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos5_verse_12.mp3', '', 1761754199, 1761754199),
(45860, 'Amos 5:13', 'Amos', 5, 13, 'نو په داسې بد وخت کې باید هوښیار انسان چوپ پاتې شي!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos5_verse_13.mp3', '', 1761754199, 1761754199),
(45861, 'Amos 5:14', 'Amos', 5, 14, 'نېک کارونه کوئ او بد کارونه مه کوئ، نو تاسو به ژوندي پاتې شئ. بیا به مطلق قادر څښتن خدای په رښتیا ستاسو سره مل وي، لکه څنګه چې تاسو دعوه کوئ چې هغه ستاسو سره مل دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos5_verse_14.mp3', '', 1761754199, 1761754199),
(45862, 'Amos 5:15', 'Amos', 5, 15, 'د بدۍ نه کرکه کوئ، د نېکۍ سره مینه کوئ او په محکمو کې عدالت ټینګ کړئ. نو کېدای شي چې مطلق قادر څښتن خدای د اسراییلو په هغو خلکو باندې چې ژوندي پاتې شوي دي، رحم وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos5_verse_15.mp3', '', 1761754199, 1761754199),
(45863, 'Amos 5:16', 'Amos', 5, 16, 'نو مطلق قادر څښتن خدای داسې وایي: «په ټولو چوکونو کې به ژړاګانې او په ټولو کوڅو کې به انګولا وي. تر دې چې بزګران به هم د ژړا دپاره راوغوښتل شي او ماتم کوونکي به د ویر دپاره راوغوښتل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos5_verse_16.mp3', '', 1761754199, 1761754199),
(45864, 'Amos 5:17', 'Amos', 5, 17, 'د انګورو په ټولو باغونو کې به ژړا او انګولا وي، ځکه چې زه به تاسو ته د سزا ورکولو دپاره راشم.» دا هغه څه دي چې څښتن ویلي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos5_verse_17.mp3', '', 1761754199, 1761754199),
(45865, 'Amos 5:18', 'Amos', 5, 18, 'افسوس ستاسو په حال چې د څښتن د ورځې د راتللو ارمان کوئ! تاسو ولې هغه ورځ غواړئ؟ دا به ستاسو دپاره د رڼا نه، بلکې د تیارې ورځ وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos5_verse_18.mp3', '', 1761754199, 1761754199),
(45866, 'Amos 5:19', 'Amos', 5, 19, 'دا به داسې وي لکه څوک چې د زمري نه منډې وهي او د اېږې سره مخامخ شي! یا چې څوک کور ته راورسیږي او په دېوال باندې لاس کېږدي او مار یې وچیچي!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos5_verse_19.mp3', '', 1761754199, 1761754199),
(45867, 'Amos 5:20', 'Amos', 5, 20, 'د څښتن ورځ به رڼا نه، بلکې تیاره راولي. دا به د تورې تیارې ورځ وي او هېڅ رڼایي به نه لیدل کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos5_verse_20.mp3', '', 1761754199, 1761754199),
(45868, 'Amos 5:21', 'Amos', 5, 21, 'څښتن وایي: «ستاسو د اخترونو څخه کرکه لرم او ستاسو مذهبي غونډې ما نه شي خوشحالولی!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos5_verse_21.mp3', '', 1761754199, 1761754199),
(45869, 'Amos 5:22', 'Amos', 5, 22, 'کله چې تاسو ماته سوځېدونکې نذرانې او د غلو دانو نذرانې راوړئ، نو زه به یې نه قبلوم. که تاسو ماته هغه حیوانات چې تاسو چاغ کړي دي، د سلامتۍ د نذرانو په توګه راوړئ، نو زه به یې پروا ونه کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos5_verse_22.mp3', '', 1761754199, 1761754199),
(45870, 'Amos 5:23', 'Amos', 5, 23, 'خپل د شورماشور نه ډکې سندرې مو بس کړئ. زه نه غواړم چې ستاسو د چنګ اوازونه واورم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos5_verse_23.mp3', '', 1761754199, 1761754199),
(45871, 'Amos 5:24', 'Amos', 5, 24, 'خو د دې په ځای دې انصاف د ویالې په شان روان وي او عدالت دې د هغه سیند په شان چې هېڅکله نه وچیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos5_verse_24.mp3', '', 1761754199, 1761754199),
(45872, 'Amos 5:25', 'Amos', 5, 25, 'ای د اسراییلو خلکو، څلوېښت کاله چې تاسو په دښته کې وئ، ایا ما ستاسو نه قربانۍ او نذرانې غوښتي دي؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos5_verse_25.mp3', '', 1761754199, 1761754199),
(45873, 'Daniel 9:1', 'Daniel', 9, 1, 'د مادى د اخسويرس د زوئ داريوس د بادشاهۍ په اول کال څوک چې د بابليانو بادشاه جوړ شو،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel9_verse_1.mp3', '', 1761754199, 1761754199),
(45874, 'Daniel 9:2', 'Daniel', 9, 2, 'د هغۀ د بادشاهۍ په اول کال، زۀ دانيال د مقدسو صحيفو نه پوهه شوم، د مالِک خُدائ د هغه کلام په مطابق چې هغۀ يرمياه نبى له ورکړے وو، چې يروشلم به د اويا کاله پورې وران وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel9_verse_2.mp3', '', 1761754199, 1761754199),
(45875, 'Daniel 9:3', 'Daniel', 9, 3, 'نو بيا زۀ مالِک خُدائ ته راوګرځېدم او هغۀ ته مې مِنت زارى وکړه او روژه مې ونيوله، او ما د ټاټ جامې واغوستلې او په خپل ځان مې ايره ونوستله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel9_verse_3.mp3', '', 1761754199, 1761754199),
(45876, 'Daniel 9:4', 'Daniel', 9, 4, 'ما خپل مالِک خُدائ نه دُعا وغوښتله او اقرار مې وکړو، ”اے مالِکه، تۀ لوئ او حېرانونکے خُدائ يې، څوک چې د خپلې مينې وعده د هغوئ سره قائمه ساتى څوک چې تا سره مينه کوى او ستا حُکمونه منى،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel9_verse_4.mp3', '', 1761754199, 1761754199),
(45877, 'Daniel 9:5', 'Daniel', 9, 5, 'مونږ ګناه کړې ده او غلط کارونه مو کړى دى. مونږ بدعملى کړې ده او سرکشى مو کړې ده، مونږ ستا د احکاماتو او شريعت نه مخ اړولے دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel9_verse_5.mp3', '', 1761754199, 1761754199),
(45878, 'Daniel 9:6', 'Daniel', 9, 6, 'مونږ ستا خِدمت کوونکو پېغمبرانو ته غوږ ونۀ نيولو، چا چې ستا په نوم زمونږ بادشاهانو، زمونږ شهزادګانو او پلار نيکونو، او زمونږ د مُلک ټولو خلقو ته خبرې وکړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel9_verse_6.mp3', '', 1761754199, 1761754199),
(45879, 'Daniel 9:7', 'Daniel', 9, 7, 'مالِکه، تۀ صادق يې، خو نن ورځ مونږ د يهوداه او يروشلم او د ټول بنى اِسرائيل خلق، نزدې او لرې شرمنده يو، په هغه ټولو مُلکونو کښې چرته چې تا مونږ د خپلو غدارى په وجه خوارۀ کړى يُو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel9_verse_7.mp3', '', 1761754199, 1761754199),
(45880, 'Daniel 9:8', 'Daniel', 9, 8, 'اے مالِکه خُدايه، مونږ او زمونږ بادشاهان، زمونږ شهزادګان او زمونږ پلار نيکونه په شرمونو شرمنده يُو ځکه چې مونږ ستا خلاف ګناه کړې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel9_verse_8.mp3', '', 1761754199, 1761754199),
(45881, 'Daniel 9:9', 'Daniel', 9, 9, 'خو مالِک خُدائ زمونږ خُدائ پاک مهربانه او بخښونکے دے، اګر چې مونږ د هغۀ خلاف بغاوت کړے دے،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel9_verse_9.mp3', '', 1761754199, 1761754199),
(45882, 'Daniel 9:10', 'Daniel', 9, 10, 'مونږ د خپل مالِک خُدائ تابعدارى نۀ ده کړې او د هغۀ هغه حُکمونه مو نۀ دى منلى کوم چې هغۀ مونږ ته د خپل خِدمت کوونکو پېغمبرانو په ذريعه راکړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel9_verse_10.mp3', '', 1761754199, 1761754199),
(45883, 'Daniel 9:11', 'Daniel', 9, 11, 'ټولو بنى اِسرائيلو ستا د شريعت خلاف ورزى کړې ده، مخ يې ترې نه اړولے دے او ستا د منلو نه يې اِنکار کړے دے. نو په دې وجه هغه لعنتونه او قسم خوړلے شوى افتونه چې د خُدائ پاک د خِدمت کوونکى موسىٰ په شريعت کښې ليکلے شوى دى په مونږ نازل شول، ځکه چې مونږ ستا خلاف ګناه کړې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel9_verse_11.mp3', '', 1761754199, 1761754199),
(45884, 'Daniel 9:12', 'Daniel', 9, 12, 'تا په مونږ د افت راوستلو په ذريعه څۀ چې دې زمونږ د بادشاهانو په خلاف فرمائيلى وُو هغه دې پوره کړل. د آسمان د لاندې هيڅکله هم داسې افتونه نۀ دى راغلى لکه څنګه چې په يروشلم راغلل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel9_verse_12.mp3', '', 1761754199, 1761754199),
(45885, 'Daniel 9:13', 'Daniel', 9, 13, 'څنګه چې د موسىٰ په شريعت کښې ليکلے شوى دى، هغه ټول افتونه په مونږ نازل شوى دى، بيا اوس هم مونږ د خپل مالِک خُدائ د رضا حاصلولو دپاره د خپلو ګناهونو نه اوړېدلى نۀ يُو او نۀ مو ستا په حقيقت غور کړے دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel9_verse_13.mp3', '', 1761754199, 1761754199),
(45886, 'Daniel 9:14', 'Daniel', 9, 14, 'نو مالِک خُدائ هم په مونږ د افت راوستلو څۀ پرواه ونۀ کړه، ځکه چې زمونږ مالِک خُدائ په خپلو ټولو کارونو کښې صادق دے، خو بيا هم مونږ د هغۀ تابعدارى ونۀ کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel9_verse_14.mp3', '', 1761754199, 1761754199),
(45887, 'Daniel 9:15', 'Daniel', 9, 15, 'اوس اے مالِکه زمونږ خُدايه، تا چا چې خپل خلق د مِصر نه په خپل زورَور لاس راوويستل او خپل نوم له دې عزت او جلال ورکړو چې تر ننه قائم دے، د دې باوجود هم مونږ ګناه وکړه، مونږ بدکارونه وکړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel9_verse_15.mp3', '', 1761754199, 1761754199),
(45888, 'Daniel 9:16', 'Daniel', 9, 16, 'اے مالِکه، په خپلو کارونو کښې تۀ صادق يې، نو په دې وجه تۀ خپله سخته غصه او غضب د خپل ښار يروشلم، ستا مقدس غر نه لرې کړه. زمونږ ګناهونو او زمونږ د پلار نيکونو ګناهونو يروشلم او ستا خلق د ګېرچاپېره قومونو د خندا کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel9_verse_16.mp3', '', 1761754199, 1761754199),
(45889, 'Daniel 9:17', 'Daniel', 9, 17, 'نو اوس اے مالِکه خُدايه، د خپل خِدمت کوونکى زما دُعا او زارۍ ته غوږ ونيسه. اے مالِکه خُدايه د خپل نوم په خاطر خپل تباه شوى پاک کور ته د رحم په نظر وګوره.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel9_verse_17.mp3', '', 1761754199, 1761754199),
(45890, 'Daniel 9:18', 'Daniel', 9, 18, 'اے خُدايه، غوږ ونيسه او واوره، خپلې سترګې کولاو کړه او هغه کنډر شوے ښار وګوره چې ستا په نوم پورې تړلے شوے دے. مونږ تا ته سوال زارى د دې دپاره نۀ کوُو چې مونږ صادقان يُو، خو ځکه چې تۀ ډېر مهربانه يې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel9_verse_18.mp3', '', 1761754199, 1761754199),
(45891, 'Daniel 9:19', 'Daniel', 9, 19, 'اے مالِکه واوره، اے خُدايه مونږ معاف کړه. اے مالِکه زمونږ واوره او عمل پرې وکړه. اے زما خُدايه د خپل ځان د خاطره دې مۀ ايسارېږه، ځکه چې ستا ښار او ستا قوم ستا په نوم پورې تړلے شوى دى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel9_verse_19.mp3', '', 1761754199, 1761754199),
(45892, 'Daniel 9:20', 'Daniel', 9, 20, 'نو چې کله ما خبرې او دُعا کوله او د خپلې ګناه او زما د قوم د بنى اِسرائيلو د ګناه اقرار مې کولو او خپل مالِک خُدائ ته مې د هغۀ د مقدس غر دپاره زارى کوله،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel9_verse_20.mp3', '', 1761754199, 1761754199),
(45893, 'Daniel 9:21', 'Daniel', 9, 21, 'ما لا دُعا کوله چې جبرائيل، هغه سړے چې ما مخکښې په رويا کښې ليدلے وو ما له په تېزۍ سره راغلو، د ماښام د قربانۍ وخت وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel9_verse_21.mp3', '', 1761754199, 1761754199),
(45894, 'Daniel 9:22', 'Daniel', 9, 22, 'هغۀ زۀ پوهه کړم او ما ته يې وفرمائيل، ”اے دانياله، زۀ اوس راغلم چې تا له پوهه او حکمت درکړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel9_verse_22.mp3', '', 1761754199, 1761754199),
(45895, 'Daniel 9:23', 'Daniel', 9, 23, 'څنګه چې تا دُعا شروع کړه نو هغې ته جواب ورکړے شو، زۀ د هغې وئيلو دپاره تا له راغلم ځکه چې تۀ ډېر قدرمند يې. په دې وجه دې پېغام ته په خيال سره غوږ شه او په رويا ځان پوهه کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel9_verse_23.mp3', '', 1761754199, 1761754199),
(45896, 'Daniel 9:24', 'Daniel', 9, 24, 'اويا وارې اووۀ کاله ستا قوم او ستا مقدس ښار دپاره مقرر شوى دى چې په کښې خپله سرکشى ختمه کړئ، او ګناه بنده کړئ، د بدعملۍ کفاره ورکړئ، نۀ ختمېدونکے صداقت قائم کړئ، د پېغمبرى رويا او پېشګوئې تصديق وکړئ او چې د ټولو نه مقدس ځائ مسح کړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel9_verse_24.mp3', '', 1761754199, 1761754199),
(45897, 'Daniel 9:25', 'Daniel', 9, 25, 'په دې غور وکړئ او ځان پرې پوهه کړئ. دوه شپېتۀ وارې اووۀ کاله به تير شى د کوم وخت نه چې د يروشلم د بيا جوړولو حُکم ورکړے شوے دے ترڅو چې مالِک خُدائ مسح کړے شوے بادشاه راشى. يروشلم به سره د کوڅو او حِفاظتى خندقونو جوړ کړے شى، خو کۀ څۀ هم چې په يروونکى وخت کښې وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel9_verse_25.mp3', '', 1761754199, 1761754199),
(45898, 'Daniel 9:26', 'Daniel', 9, 26, 'د دې دوه شپېتۀ وارې اووۀ کاله نه وروستو به مسح کړے شوے کس قتل کړے شى او هغۀ سره به څۀ نۀ وى. نو په هغه وخت کښې به بيا بل حکمران راوچت شى د چا لښکرې به چې دا ښار او د خُدائ کور تباه کړى. د دې خاتمه به لکه د سېلاب راشى، او د جنګ او د هغې بدبختى به د آخر پورې جارى وى، او د هغې تباهۍ حکم جارى شوے دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel9_verse_26.mp3', '', 1761754199, 1761754199),
(45899, 'Daniel 9:27', 'Daniel', 9, 27, 'هغه حکمران به د اووۀ کالو دپاره د ډېرو خلقو سره لوظ وکړى او د دې وخت په نيمه کښې به هغه قربانۍ او نذرانې ختمې کړى. او د مالِک خُدائ د کور په اوچت ځائ به يو داسې ناپاکه بُت کېږدى چې تباهى به راولى. او تر هغې پورې به هلته وى ترڅو چې خُدائ پاک هغه خپل اَنجام ته ورسوى کوم چې ورته هغۀ مقرر کړے دے.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel9_verse_27.mp3', '', 1761754199, 1761754199),
(45900, 'Psalms 120:1', 'Psalms', 120, 1, 'ما د سختۍ په وخت کې وکړ فریاد څښتن ته او هغه قبوله کړه دعا زما', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms120_verse_1.mp3', '', 1761754199, 1761754199),
(45901, 'Psalms 120:2', 'Psalms', 120, 2, 'ما له دروغجنو او مکارو خلکو وساته ای څښتنه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms120_verse_2.mp3', '', 1761754199, 1761754199),
(45902, 'Psalms 120:3', 'Psalms', 120, 3, 'ای مکارو خلکو، خدای به څه کوي له تاسو سره؟ تاسو ته څرنګه سزا به درکړي؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms120_verse_3.mp3', '', 1761754199, 1761754199),
(45903, 'Psalms 120:4', 'Psalms', 120, 4, 'په تېرو غشو د عسکرو به سزا درکړي او په سرو سکروټو باندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms120_verse_4.mp3', '', 1761754199, 1761754199),
(45904, 'Psalms 120:5', 'Psalms', 120, 5, 'افسوس دې وي په ما چې زه اوسېږمه په ماشک کې د مسافر په شان او هم اوسېږم د قیدار خېمو کې لکه پردي په شان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms120_verse_5.mp3', '', 1761754199, 1761754199),
(45905, 'Psalms 120:6', 'Psalms', 120, 6, 'د هغو خلکو سره زه زیات اوسېدلی یمه څوک چې نفرت کوي له سولې څخه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms120_verse_6.mp3', '', 1761754199, 1761754199),
(45906, 'Psalms 120:7', 'Psalms', 120, 7, 'زه غواړم سوله خو چې زه کوم خبرې د سولې هغوی جنګ غواړي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms120_verse_7.mp3', '', 1761754199, 1761754199),
(45907, 'Leviticus 9:1', 'Leviticus', 9, 1, 'د کاهنانو د ټاکنې د مراسمو څخه وروسته موسی په اتمه ورځ هارون او د هغه زامن او د اسراییلو مشران راوغوښتل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus9_verse_1.mp3', '', 1761754199, 1761754199),
(45908, 'Leviticus 9:2', 'Leviticus', 9, 2, 'هغه هارون ته وویل: «یو خوسی او یو پسه چې کوم عیب په کې نه وي، واخله او څښتن ته یې وړاندې کړه. خوسی د ګناه د نذرانې دپاره دی او پسه د سوځېدونکې نذرانې دپاره دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus9_verse_2.mp3', '', 1761754199, 1761754199),
(45909, 'Leviticus 9:3', 'Leviticus', 9, 3, 'بیا د اسراییلو خلکو ته ووایه: یو سېرلی د ګناه د نذرانې دپاره واخلئ. یو خوسی چې یو کلن وي او یو وری چې یو کلن وي او هېڅ عیب په کې نه وي، د سوځېدونکې نذرانې دپاره واخلئ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus9_verse_3.mp3', '', 1761754199, 1761754199),
(45910, 'Leviticus 9:4', 'Leviticus', 9, 4, 'او یو غویی او یو پسه د سلامتۍ د نذرانې دپاره. هغوی دې دا د څښتن په حضور کې د غلې دانې د نذرانې سره چې تېل ورسره ګډ وي، قرباني کړي. هغوی باید دا کار وکړي، ځکه چې څښتن به نن هغوی ته ورښکاره شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus9_verse_4.mp3', '', 1761754199, 1761754199);